//メッセージボックス0(AutoMode)の文字設定
//メッセージは最大4,294,967,295通り
	
	CASE HMI_MessageNo[0] OF
	
	INT#0 :
	HMI_Message[0] := '' ;
    INT#1 :
	HMI_Message[0] := 'Running・・・' ;
	INT#2 :
	HMI_Message[0] := 'Core R Inversion NG' ;
	INT#3 :
	HMI_Message[0] := 'Core L Inversion NG' ;
	INT#4 :
	HMI_Message[0] := 'Incorrect Container Orientation' ;
	INT#5 :
	HMI_Message[0] := 'Packed Container Full' ;
     INT#6 :
	HMI_Message[0] := 'No Container Added' ;
	INT#7 :
	HMI_Message[0] := 'Paused・・・' ;
    INT#8 :
	HMI_Message[0] := 'R Stock Holder Qty Error' ;
	INT#9 :
	HMI_Message[0] := 'L Stock Holder Qty Error' ;
    INT#10 :
	HMI_Message[0] := 'Step Running・・・' ;
	INT#11 :
	HMI_Message[0] := 'Work Discharge Complete' ;
	INT#12 :
	HMI_Message[0] := 'SD Error' ;
	END_CASE;

//メッセージボックス0(AutoMode)の文字設定
//メッセージは最大4,294,967,295通り
	
	CASE HMI_MessageNo[0] OF
	
	INT#0 :
	HMI_Message[0] := '' ;
	INT#1 :
	HMI_Message[0] := '運転中・・・' ;	
	INT#2 :
	HMI_Message[0] := 'コアR反転 NG' ;	
    INT#3 :
	HMI_Message[0] := 'コアR反転 NG' ;
	INT#4 :
	HMI_Message[0] := 'コンテナ方向 違い' ;
	INT#5 :
	HMI_Message[0] := '梱包済みコンテナ 満杯 or 排出詰まり' ;
    INT#6 :
	HMI_Message[0] := 'コンテナ 無 追加してください' ;
    INT#7 :
	HMI_Message[0] := '一時停止中・・・' ;
    INT#8 :
	HMI_Message[0] := '右ストックフォルダ 入数ミス 取り除いて 再スタート' ;
    INT#9 :
	HMI_Message[0] := '左ストックフォルダ 入数ミス 取り除いて 再スタート' ;
	INT#10 :
	HMI_Message[0] := 'ステップ運転中・・・' ;
